"""Euler-gap promise class: exponent reduction and the Fermat-gcd split."""
import math
import random


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def euler_gap_pairs(lo: int, hi: int, mult_max: int, count: int, seed: int = 0) -> list[tuple[int, int]]:
    """Random primes p in [lo, hi) together with a prime q = k(p-1) + 1, so (p-1) | (q-1)."""
    rng = random.Random(seed)
    out: list[tuple[int, int]] = []
    while len(out) < count:
        p = rng.randrange(lo, hi)
        if not is_prime(p):
            continue
        for k in range(2, mult_max + 1):
            q = k * (p - 1) + 1
            if is_prime(q):
                out.append((p, q))
                break
    return out


def first_splitting_base(N: int, B: int = 100) -> tuple[int, int] | None:
    for x in range(2, B + 1):
        g = math.gcd((pow(x, N - 1, N) - 1) % N, N)
        if 1 < g < N:
            return x, g
    return None


def main() -> None:
    print("Exponent reduction x^(pq-1) = x^(q-1) (mod p):")
    for p, q in ((11, 31), (13, 37), (101, 601)):
        assert all(pow(x, p * q - 1, p) == pow(x, q - 1, p) for x in range(1, p))
        print(f"  verified for every x in 1..{p-1} with (p, q) = ({p}, {q})")
    print("\nEuler-gap semiprimes ((p-1) | (q-1)):")
    for p, q in euler_gap_pairs(10_000, 50_000, 40, 8):
        res = first_splitting_base(p * q)
        print(f"  N = {p} * {q} = {p*q}:  first splitting base/factor = {res}")
    print("\nControl: random balanced semiprimes (gcd(p-1,q-1) small):")
    rng = random.Random(7)
    primes = [n for n in range(10_000, 12_000) if is_prime(n)]
    for _ in range(6):
        p, q = rng.sample(primes, 2)
        print(f"  N = {p} * {q}, gcd(p-1,q-1) = {math.gcd(p-1, q-1)}:  split = {first_splitting_base(p*q)}")


if __name__ == "__main__":
    main()

