from fractions import Fraction


def order_constrained_optimum(omega: Fraction) -> tuple[Fraction, Fraction, Fraction]:
    """Exact minimiser of c(a,b) = max{a, b, 1/2 - a/2 - b} subject to b <= omega.

    Returns (a, b, value) with value = max(1/5, (1 - 2 omega)/3).
    """
    fifth = Fraction(1, 5)
    if omega >= fifth:
        return fifth, fifth, fifth
    v = (1 - 2 * omega) / 3
    return v, omega, v


def cost_exp(a: Fraction, b: Fraction) -> Fraction:
    return max(a, b, Fraction(1, 2) - a / 2 - b)


def lower_bound_certificate(a: Fraction, b: Fraction, omega: Fraction) -> Fraction:
    """max of the two linear certificates; always <= cost_exp(a, b) when b <= omega."""
    legs = (a, b, Fraction(1, 2) - a / 2 - b)
    cert_fifth = Fraction(1, 5) * legs[0] + Fraction(2, 5) * legs[1] + Fraction(2, 5) * legs[2]
    cert_order = (legs[0] + 2 * legs[2]) / 3 + Fraction(2, 3) * (b - omega)  # = (1 - 2 omega)/3
    return max(cert_fifth, cert_order)


if __name__ == "__main__":
    for w in (Fraction(0), Fraction(1, 10), Fraction(1, 5), Fraction(1, 3), Fraction(1)):
        a, b, v = order_constrained_optimum(w)
        assert b <= w and cost_exp(a, b) == v
        print(f"omega = {w}: optimum {v} at (a, b) = ({a}, {b})")

import math


def harvey_time_log(log2N: float, log2r: float, log2m: float) -> float:
    """log2 of T(r,m) = (sqrt(N)/(sqrt(r) m) + r) L^4 + m L^2, with L = log2 N."""
    lL = math.log2(log2N)
    terms = [0.5 * log2N - 0.5 * log2r - log2m + 4 * lL,  # giant-step interior Y
             log2r + 4 * lL,                                # pair leg X
             log2m + 2 * lL]                                # baby-step leg Z
    mx = max(terms)
    return mx + math.log2(sum(2 ** (t - mx) for t in terms))


def balanced_parameters(log2N: float) -> dict[str, float]:
    """Balanced point r* = N^{1/5} L^{-4/5}, m* = N^{1/5} L^{6/5}; all legs equal F."""
    lL = math.log2(log2N)
    log2F = 0.2 * log2N + 3.2 * lL
    log2r = 0.2 * log2N - 0.8 * lL
    log2m = 0.2 * log2N + 1.2 * lL
    log2T = harvey_time_log(log2N, log2r, log2m)
    return {"log2_r": log2r, "log2_m": log2m, "log2_F": log2F,
            "log2_T": log2T, "T_over_F": 2 ** (log2T - log2F)}


if __name__ == "__main__":
    for bits in (256, 512, 1024, 2048):
        p = balanced_parameters(bits)
        print(f"{bits}-bit N: r* = 2^{p['log2_r']:.1f}, m* = 2^{p['log2_m']:.1f}, "
              f"F = 2^{p['log2_F']:.1f}, T/F = {p['T_over_F']:.6f}")

import math


def euler_gap_split(N: int, max_base: int = 100) -> tuple[int, int] | None:
    """Try gcd(x^{N-1} - 1, N) for bases x = 2..max_base; return (x, factor) or None.

    Guaranteed to succeed on N = pq with (p-1) | (q-1) as soon as some base x
    has p not dividing x and q not dividing x^{N-1} - 1.
    """
    for x in range(2, max_base + 1):
        g = math.gcd(x, N)
        if 1 < g < N:
            return x, g
        g = math.gcd((pow(x, N - 1, N) - 1) % N, N)
        if 1 < g < N:
            return x, g
    return None


if __name__ == "__main__":
    for p, q in ((11, 31), (13, 37), (101, 601), (1019, 1031)):
        print(f"N = {p}*{q} = {p*q}, gcd(p-1,q-1) = {math.gcd(p-1, q-1)}: "
              f"{euler_gap_split(p * q, 50)}")
